package com.bananalab.lite;
import android.content.Context;import android.graphics.*;import java.util.regex.*;import java.util.*;
/** Own learned compositional masks + own learned face/accessory patches. */
final class CustomCharacter{
 static final String SHAPES="redondo|redonda|ovalado|ovalada|cuadrado|cuadrada|estrella|gota|capsula";
 static int shape(String look){return look.contains("ovalad")?1:look.contains("cuadrad")?2:look.contains("estrella")?3:look.contains("gota")?4:look.contains("capsula")?5:0;}
 static int ears(String look){return look.contains("orejas redondas")?1:look.contains("orejas largas")?2:look.contains("orejas puntiagudas")?3:0;}
 static int tail(String look){return look.contains("cola larga")?2:look.contains("cola corta")?1:0;}
 static CreatorSession.Result apply(String input,SceneDraft base)throws Exception{String q=CreationRequest.normalize(input);Matcher named=Pattern.compile("(?:crea|dibuja|disena|haceme)(?: a)? ([a-z]{2,20}) (?:un|una) (?:personaje|criatura|monstruo)(.*)").matcher(q),simple=Pattern.compile("(?:crea|dibuja|disena|haceme) (?:un|una) (?:personaje|criatura|monstruo)(.*)").matcher(q),add=Pattern.compile("agrega (?:un|una) (?:personaje|criatura|monstruo)(?: llamado| llamada)? ([a-z]{2,20})(.*)").matcher(q);
  if(named.matches()||simple.matches()||add.matches()){boolean n=named.matches(),a=add.matches();String label=n?named.group(1):a?add.group(1):"",traits=n?named.group(2):a?add.group(2):simple.group(1);if(traits.matches("(?s).*\\b(?:baila|salta|camina|dice|entrega|habla)\\b.*"))return CreatorSession.say("Primero describí la criatura; después agregá su acción o diálogo.");String unknown=traits.replaceAll("\\b(?:"+SHAPES+"|"+SceneConversation.COLORS+"|con|y|sin|orejas|redondas|largas|puntiagudas|cola|corta|larga|sombrero|corona|lentes|anteojos|gafas|cuerpo|alto|bajo|delgado|ancho|ojos|grandes|pequenos|normales)\\b","").trim();if(!unknown.isEmpty())return CreatorSession.say("No entendí estos rasgos: «"+unknown+"». Puedo combinar cuerpos redondo, ovalado, cuadrado, estrella, gota o cápsula; orejas, cola, color y accesorios.");SceneDraft d=a&&base!=null?base.copy():new SceneDraft();if(d.cast.size()>=4)return CreatorSession.say("Esta toma admite cuatro personajes.");SceneDraft.Actor actor=new SceneDraft.Actor(SceneDirector.unique(d,"criatura"),a?SceneConversation.freePosition(d):50);actor.kind="criatura";actor.label=label;actor.look=traits.trim();if(!actor.look.matches("(?s).*\\b(?:"+SHAPES+")\\b.*"))actor.look="redondo "+actor.look;d.cast.add(actor);d.focused=actor.name;return new CreatorSession.Result(true,"Creé una criatura combinando cuerpo, orejas y cola con el campo neuronal propio. Podés ajustar Forma, Orejas y Cola en el editor.",d);}
  Matcher body=Pattern.compile("(?:cambia|pone) (?:el )?cuerpo de (.+?) (?:a|como|en) ("+SHAPES+")").matcher(q),part=Pattern.compile("pone (orejas (?:redondas|largas|puntiagudas)|sin orejas|cola (?:corta|larga)|sin cola) (?:a|en) (.+)").matcher(q);if(!body.matches()&&!part.matches())return null;if(base==null)return CreatorSession.say("Primero creá una criatura.");boolean b=body.matches();String who=b?body.group(1):part.group(2),value=b?body.group(2):part.group(1);SceneDraft.Actor old=ScenePlanner.resolve(base,who,false);if(old==null||!old.kind.equals("criatura"))return CreatorSession.say("Ese control corresponde a una criatura combinable. Nombrá una del proyecto.");SceneDraft d=base.copy();String category=b?SHAPES:value.contains("orejas")?"sin orejas|orejas (?:redondas|largas|puntiagudas)":"sin cola|cola (?:corta|larga)";d.get(old.name).look=SceneDirector.replace(old.look,category,value);d.focused=old.name;return new CreatorSession.Result(true,"Cambié solo esa parte de la criatura, conservando identidad, color y acciones.",d);
 }
 private static final LinkedHashMap<String,Bitmap> cache=new LinkedHashMap<>(16,.75f,true);
 static Bitmap image(Context c,SceneDraft.Actor a,int expression,int view)throws Exception{int nv=view==3?2:view==0?0:1;String key=a.look+"|"+expression+"|"+view; synchronized(CustomCharacter.class){Bitmap hit=cache.get(key);if(hit!=null)return hit;}
  Bitmap mask;try(java.io.InputStream in=c.getAssets().open("custom23/bank/s"+shape(a.look)+"-e"+ears(a.look)+"-t"+tail(a.look)+"-v"+nv+".png")){mask=BitmapFactory.decodeStream(in);}int[] labels=new int[4096],pixels=new int[16384];mask.getPixels(labels,0,64,0,0,64,64);mask.recycle();int color=Scene.bodyColor("criatura",a.look);for(int y=0;y<128;y++)for(int x=0;x<128;x++){int label=Math.round((labels[(y/2)*64+x/2]&255)/85f);pixels[y*128+x]=label==0?0:label==1?color:0xff352b40;}Bitmap out=Bitmap.createBitmap(128,128,Bitmap.Config.ARGB_8888);out.setPixels(pixels,0,128,0,0,128,128);Canvas canvas=new Canvas(out);Paint p=new Paint(Paint.FILTER_BITMAP_FLAG);boolean glasses=Appearance.has(a.look,"lentes|anteojos|gafas");
  if(nv!=2){int eyes=Appearance.has(a.look,"ojos grandes")?2:Appearance.has(a.look,"ojos pequenos|ojos chicos")?1:0;try(java.io.InputStream in=c.getAssets().open("pixel22/faces/4-"+expression+"-"+nv+"-"+eyes+"-"+(glasses?1:0)+".png")){Bitmap face=BitmapFactory.decodeStream(in);float width=nv==1?20.3f:26;canvas.drawBitmap(face,null,new RectF((32-width/2)*2,46,(32+width/2)*2,94),p);face.recycle();}}
  int acc=Appearance.has(a.look,"corona")?2:Appearance.has(a.look,"sombrero")?1:0;if(acc>0){String asset="pixel-v2/bank/k4-ff8cc8df-"+acc+"-0"+(nv>0?"-v"+nv:"")+".webp";try(java.io.InputStream in=c.getAssets().open(asset)){Bitmap hat=BitmapFactory.decodeStream(in);canvas.drawBitmap(hat,new Rect(0,0,128,42),new RectF(0,6,128,48),p);hat.recycle();}catch(Exception ignored){/* Character shape remains valid if a legacy accessory palette is unavailable. */}}
  if(view==2){Matrix m=new Matrix();m.setScale(-1,1);out=Bitmap.createBitmap(out,0,0,128,128,m,true);}synchronized(CustomCharacter.class){cache.put(key,out);while(cache.size()>32)cache.remove(cache.keySet().iterator().next());}return out;
 }
}
